/* Explicit investment mortgages. Price/yield/tax assumptions are game estimates. */
(function(root){
'use strict';
const month=()=>S.age*12+Math.floor((S.t||0)*12+1e-6),usd=n=>LifelineEconomy.toUSD(n);
function state(){return S.lifelineRentalFinance||(S.lifelineRentalFinance={loans:{},serial:0,lastBuy:null,lastYear:null});}
function debt(){return Object.values(state().loans).reduce((sum,l)=>sum+l.balance,0);}
function payment(balance,rate,years){return balance<=0?0:rate>0?balance*rate/(1-Math.pow(1+rate,-years)):balance/years;}
function operating(value,size,country,foreign=false){const gross=value*rentY(country)*(size==='s'?1.3:1),vacancy=gross*RENT_VAC_P*4/12,rent=gross-vacancy,maintenance=value*rentCost(country),management=foreign?rent*.09:0,tax=Math.max(0,rent-maintenance-management)*.15;return {gross,vacancy,rent,maintenance,management,tax,net:rent-maintenance-management-tax};}
function quote(size,mode='auto',cash=cashV()){const c=C(),v=housePrice(c)*(size==='b'?1:.55),buy=v*(c.id==='KOR'&&(S.house>0?1:0)+rentals().length>=2?.08:.03),ltv=c.id==='KOR'?(S.house>0||rentals().length?.5:.7):c.p==='hi'?.75:.6,loan=mode==='cash'?0:mode==='loan'?v*ltv:Math.min(v*ltv,Math.max(0,v+buy-cash)),down=v+buy-loan,rate=lowInc(c)?.06:Math.max(.01,mortR(c)),years=Math.max(5,Math.min(25,80-S.age)),annualPayment=payment(loan,rate,years),o=operating(v,size,c),interest=loan*rate,principal=Math.min(loan,Math.max(0,annualPayment-interest)),otherPayments=Object.values(state().loans).reduce((n,l)=>n+l.payment,0)+Math.max(0,-S.money)*.06,income=Math.max(0,shopInc())+.7*(o.net+rentals().reduce((n,r)=>n+Math.max(0,operating(r.v,r.k,CBY[r.c]||c,r.c!==S.cur).net),0));let reason=!rentOK()?'Покупка под аренду недоступна: нужен возраст 25–79 лет, постоянное место жительства и завершённая учёба':vowedHome()?'Недоступно при текущем укладе жизни':rentals().length>=RENT_MAX?'Можно владеть не более чем тремя доходными домами':state().lastBuy!=null&&month()-state().lastBuy<12?'Следующая покупка под аренду доступна через '+(12-(month()-state().lastBuy))+' мес.':loan>0&&S.age>=75?'Этот кредит нужно оформить до 75 лет':cash+1e-6<down?'Не хватает первоначального взноса: нужно '+wonStr(down)+', доступно '+wonStr(cash):loan>0&&otherPayments+annualPayment>income*.4?'Платежи превысят 40% расчётного дохода с учётом аренды':'';return {size,mode,v,buy,ltv,loan,down,rate,years,payment:annualPayment,interest,principal,...o,cashFlow:o.net-annualPayment,ok:!reason,reason};}
function attach(size,q){const s=state(),id='rental-'+(++s.serial);rentals().push({v:q.v,p:q.v,at:S.age,c:S.cur,k:size,lifelineManaged:true,lifelineLoanId:q.loan>0?id:null});if(q.loan>0)s.loans[id]={balance:q.loan,initial:q.loan,rate:q.rate,years:q.years,payment:q.payment,country:S.cur,started:month(),paidAt:month(),kind:'rental'};s.lastBuy=month();S.yearMark='buy';return 'Вы купили '+(size==='s'?'небольшой дом':'дом')+' под аренду за '+wonStr(q.v)+'. '+(q.loan>0?'Кредит: '+wonStr(q.loan)+', платёж '+wonStr(q.payment)+' в год. ':'Без кредита. ')+'Расходы на оформление: '+wonStr(q.buy)+'. Прогноз денежного потока после расходов и кредита: '+wonStr(q.cashFlow)+' в год. Это игровая оценка, доход не гарантирован.';}
function buy(size,mode){if(!['s','b'].includes(size)||!['cash','loan'].includes(mode))throw Error('Выберите дом и способ оплаты');const q=quote(size,mode);if(!q.ok)throw Error(q.reason);potDraw(q.down);S.money-=q.down;book('Первоначальный взнос и оформление доходного дома',-q.down);log(attach(size,q),'big');}
function settle(id){const s=state(),loan=s.loans[id];if(!loan)return;S.money-=loan.balance;book('Погашение кредита при продаже дома',-loan.balance);delete s.loans[id];}
function observe(){const s=state();if(S.phase!=='life')return;for(const [id,loan]of Object.entries(s.loans)){while(month()-loan.paidAt>=12&&loan.balance>1e-6){const interest=loan.balance*loan.rate,principal=Math.min(loan.balance,Math.max(0,loan.payment-interest)),paid=interest+principal;S.money-=paid;loan.balance-=principal;loan.paidAt+=12;book('Проценты по кредиту на доходный дом',-interest);book('Погашение основного долга по доходному дому',-principal);loan.last={interest,principal,payment:paid};if(S.money<0)log('После платежа по кредиту на дом денег не хватило. Платёж: '+wonStr(paid)+', из них проценты '+wonStr(interest)+'. Проверьте бюджет или продайте дом.','bad');}if(loan.balance<=1e-6){delete s.loans[id];log('Кредит на доходный дом полностью погашен.','warm');}}}
function converted(q){const keys=['v','buy','loan','down','payment','interest','principal','gross','vacancy','rent','maintenance','management','tax','net','cashFlow'];return {...q,...Object.fromEntries(keys.map(k=>[k,usd(q[k])]))};}
function summary(){const s=state();return {debt:usd(debt()),offers:['s','b'].flatMap(size=>['cash','loan'].map(mode=>converted(quote(size,mode)))),assets:rentals().map(r=>{const loan=s.loans[r.lifelineLoanId],o=operating(r.v,r.k,CBY[r.c]||C(),r.c!==S.cur),pay=loan?.payment||0;return {size:r.k,country:text(CBY[r.c]?.ko||r.c),value:usd(r.v),balance:usd(loan?.balance||0),payment:usd(pay),net:usd(o.net),cashFlow:usd(o.net-pay),legacy:!r.lifelineManaged};}),lastNet:S.flags.rentNet==null?null:usd(S.flags.rentNet),note:'Доходность, простои, обслуживание, налог и условия кредита — игровые оценки по экономической модели страны. Налог 15% здесь является правилом игры, а не актуальной ставкой закона. Прогноз не включает изменение цены дома. Старые кредиты остаются в общем долге и не приписываются домам задним числом.'};}
function install(){const worth=netWorth;netWorth=function(){return worth()-debt();};const deal=rentDeal;rentDeal=function(size,cash=cashV()){const q=quote(size,'auto',cash);return {...q,ok:q.ok};};rentBuy=function(size,paid=0,previous){const q=quote(size,'auto',previous?.m??Math.max(0,S.money+paid));if(!q.ok){S.money+=paid;return null;}return attach(size,q);};const sell=rentSell;rentSell=function(...args){const id=rentals()[0]?.lifelineLoanId,note=sell.apply(this,args);if(note&&id){const balance=state().loans[id]?.balance||0;settle(id);return note+' Из выручки погашен остаток кредита: '+wonStr(balance)+'.';}return note;};const fire=rentalFire;rentalFire=function(...args){const id=rentals().at(-1)?.lifelineLoanId,result=fire.apply(this,args);if(id)settle(id);return result;};const enter=rentIn;rentIn=function(...args){const r=rentals().find(a=>a.c===S.cur),id=r?.lifelineLoanId,note=enter.apply(this,args);if(note&&id){S.lifelineOwnLoan=id;state().loans[id].kind='home';}return note;};const homeSell=SHOP.find(i=>i.id==='sellhouse');if(homeSell){const run=homeSell.run;homeSell.run=function(...args){const id=S.lifelineOwnLoan,note=run.apply(this,args);if(note&&id){settle(id);delete S.lifelineOwnLoan;}return note;};}const shop=SHOP.find(i=>i.id==='rental');shop.d=()=> 'Покупка дома под аренду · прогноз расходов, кредита и чистого денежного потока';shop.ok=()=>rentals().length>0||rentOK();
}
root.LifelineRentalFinance={state,debt,payment,operating,quote,buy,observe,summary,install};
})(self);
